<div class="page-heading"><span class="section-kicker">Tinjau pengajuan #<?= (int) $application['id'] ?></span><h1><?= e($application['type_name']) ?></h1><p>Warga: <?= e($application['full_name']) ?> · <?= e(date('d/m/Y H:i', strtotime($application['created_at']))) ?></p></div><div class="row g-4"><div class="col-xl-7"><section class="data-panel"><div class="d-flex justify-content-between flex-wrap gap-2"><h2 class="h5">Riwayat status</h2><span class="status-pill pending"><?= e(status_label($application['status'])) ?></span></div><div class="timeline mt-4"><?php foreach ($history as $item): ?><div class="timeline-item"><strong><?= e(status_label($item['new_status'])) ?></strong><small><?= e($item['actor_name'] ?: 'Warga') ?> · <?= e(date('d/m/Y H:i', strtotime($item['created_at']))) ?></small><?php if ($item['note']): ?><small><?= e($item['note']) ?></small><?php endif; ?></div><?php endforeach; ?></div><hr><h3 class="h6">Keperluan warga</h3><p class="small text-secondary mb-0"><?= e((json_decode($application['payload'], true) ?: [])['keperluan'] ?? '') ?></p></section></div><div class="col-xl-5"><form class="data-panel" method="post" action="/admin/pengajuan/<?= (int) $application['id'] ?>"><?= csrf_field() ?><h2 class="h5">Tindakan petugas</h2><p class="small text-secondary">Tindakan divalidasi ulang menurut role dan urutan status server.</p><div class="mb-3"><label class="form-label" for="status">Tahap berikutnya</label><select class="form-select" id="status" name="status" required><?php foreach ($statuses as $key => $label): ?><option value="<?= e($key) ?>" <?= $application['status'] === $key ? 'selected' : '' ?>><?= e($label) ?></option><?php endforeach; ?></select></div><?php if (can('residents.view')): ?><fieldset class="border rounded p-3 mb-3"><legend class="float-none w-auto px-1 fs-6">Data dari dokumen asli</legend><p class="small text-secondary">Hanya diisi saat verifikator memeriksa identitas langsung.</p><div class="mb-2"><label class="form-label" for="nik">NIK</label><input class="form-control" id="nik" name="nik" inputmode="numeric" pattern="[0-9]{16}" maxlength="16" value="<?= e($application['nik']) ?>"></div><div class="mb-2"><label class="form-label" for="birth_place">Tempat lahir</label><input class="form-control" id="birth_place" name="birth_place" maxlength="100" value="<?= e($application['birth_place']) ?>"></div><div class="mb-2"><label class="form-label" for="birth_date">Tanggal lahir</label><input class="form-control" id="birth_date" name="birth_date" type="date" value="<?= e($application['birth_date']) ?>"></div><div class="mb-2"><label class="form-label" for="address">Alamat</label><textarea class="form-control" id="address" name="address" rows="2" maxlength="1000"><?= e($application['address']) ?></textarea></div><div class="row"><div class="col"><label class="form-label" for="rt">RT</label><input class="form-control" id="rt" name="rt" maxlength="5" value="<?= e($application['rt']) ?>"></div><div class="col"><label class="form-label" for="rw">RW</label><input class="form-control" id="rw" name="rw" maxlength="5" value="<?= e($application['rw']) ?>"></div></div></fieldset><?php endif; ?><div class="mb-3"><label class="form-label" for="note">Catatan / alasan</label><textarea class="form-control" id="note" name="note" rows="3" maxlength="1000"></textarea></div><button class="btn btn-success" type="submit">Simpan perubahan</button></form></div></div><a class="small d-inline-block mt-4" href="/admin/pengajuan">Kembali ke antrean</a>